    // Mocking the CapturesArguments interface/class as it is used in the method
    public interface CapturesArguments extends Matcher {
        void captureFrom(Object argument);
    }

    @Test
    public void testCaptureArgumentsFrom_AllMatchersAreCapturingAndArgumentsMatch() {
        // Arrange
        Invocation invocation = mock(Invocation.class);
        Object arg1 = "first";
        Object arg2 = "second";
        when(invocation.getArguments()).thenReturn(new Object[]{arg1, arg2});

        CapturesArguments capturer1 = mock(CapturesArguments.class);
        CapturesArguments capturer2 = mock(CapturesArguments.class);
        Matcher normalMatcher = mock(Matcher.class);

        List<Matcher> matchers = Arrays.asList(capturer1, capturer2, normalMatcher);
        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);

        // Act
        invocationMatcher.captureArgumentsFrom(invocation);

        // Assert
        verify(capturer1).captureFrom(arg1);
        verify(capturer2).captureFrom(arg2);
    }

    @Test
    public void testCaptureArgumentsFrom_FewerArgumentsThanMatchers() {
        // Arrange
        Invocation invocation = mock(Invocation.class);
        Object arg1 = "onlyOne";
        when(invocation.getArguments()).thenReturn(new Object[]{arg1});

        CapturesArguments capturer1 = mock(CapturesArguments.class);
        CapturesArguments capturer2 = mock(CapturesArguments.class);
        List<Matcher> matchers = Arrays.asList(capturer1, capturer2);
        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);

        // Act
        invocationMatcher.captureArgumentsFrom(invocation);

        // Assert
        verify(capturer1).captureFrom(arg1);
        // capturer2 should not be called because i.getArguments().length (1) is not > k (1)
        verifyZeroInteractions(capturer2);
    }

